CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, email TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_name TEXT, token_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories (id UUID PRIMARY KEY, name TEXT NOT NULL, parent_id UUID REFERENCES categories(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge (id UUID PRIMARY KEY, owner_id UUID REFERENCES users(id) ON DELETE SET NULL, category_id UUID REFERENCES categories(id) ON DELETE SET NULL, title TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'vi', content TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', visibility TEXT NOT NULL DEFAULT 'public', version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_versions (id BIGSERIAL PRIMARY KEY, knowledge_id UUID NOT NULL REFERENCES knowledge(id) ON DELETE CASCADE, editor_id UUID REFERENCES users(id) ON DELETE SET NULL, version INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, source TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS files (id UUID PRIMARY KEY, owner_id UUID REFERENCES users(id) ON DELETE SET NULL, knowledge_id UUID REFERENCES knowledge(id) ON DELETE CASCADE, filename TEXT NOT NULL, mime_type TEXT, size_bytes BIGINT, storage_path TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_knowledge_category ON knowledge(category_id);
CREATE INDEX IF NOT EXISTS idx_versions_knowledge ON knowledge_versions(knowledge_id, version DESC);